def sum_div(number):
    """Write a function to return the sum of all divisors of a number."""
    if number <= 1:
        return 0
    total = 1
    divisor = 2
    while divisor * divisor <= number:
        if number % divisor == 0:
            total += divisor
            counterpart = number // divisor
            if counterpart != divisor:
